Here is a Go HTTP server with multiple handlers:

```go
// filepath: internal/server/handlers.go

package server

import (
    "encoding/json"
    "fmt"
    "log"
    "net/http"
    "strconv"
    "strings"
    "time"
)

type Server struct {
    db     Database
    logger *log.Logger
}

type HealthResponse struct {
    Status    string `json:"status"`
    Timestamp string `json:"timestamp"`
    Version   string `json:"version"`
}

type ErrorResponse struct {
    Error   string `json:"error"`
    Code    int    `json:"code"`
}

func (s *Server) HandleHealth(w http.ResponseWriter, r *http.Request) {
    resp := HealthResponse{
        Status:    "healthy",
        Timestamp: time.Now().UTC().Format(time.RFC3339),
        Version:   "1.2.0",
    }
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(resp)
}

func (s *Server) HandleGetUsers(w http.ResponseWriter, r *http.Request) {
    users, err := s.db.ListUsers()
    if err != nil {
        s.writeError(w, "failed to list users", http.StatusInternalServerError)
        return
    }
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(users)
}

func (s *Server) HandleGetUser(w http.ResponseWriter, r *http.Request) {
    idStr := strings.TrimPrefix(r.URL.Path, "/api/users/")
    id, err := strconv.Atoi(idStr)
    if err != nil {
        s.writeError(w, "invalid user id", http.StatusBadRequest)
        return
    }
    user, err := s.db.GetUser(id)
    if err != nil {
        s.writeError(w, "user not found", http.StatusNotFound)
        return
    }
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(user)
}

func (s *Server) writeError(w http.ResponseWriter, msg string, code int) {
    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(code)
    json.NewEncoder(w).Encode(ErrorResponse{Error: msg, Code: code})
}
```

